-- Name: user_rolemap; Type: TABLE; Schema: master; Owner: postgres
--

CREATE TABLE master.user_rolemap (
    id uuid NOT NULL,
    user_role_id uuid,
    user_id uuid,
    active character varying(1),
    modified_by character varying,
    modified_date timestamp with time zone DEFAULT now(),
    created_by character varying,
    created_date timestamp with time zone DEFAULT now()
);


ALTER TABLE master.user_rolemap OWNER TO postgres;

--
-- Name: voucher_detail; Type: TABLE; Schema: master; Owner: postgres
--

CREATE TABLE master.voucher_detail (
    id uuid NOT NULL,
    voucher_id uuid NOT NULL,
    line_no integer NOT NULL,
    ledger_id uuid NOT NULL,
    cost_center_id uuid,
    debit_amount numeric(18,2),
    credit_amount numeric(18,2),
    remarks character varying(30),
    active character varying(1),
    created_by character varying(100),
    modified_by character varying(100),
    created_date timestamp with time zone,
    modified_date timestamp with time zone
);


ALTER TABLE master.voucher_detail OWNER TO postgres;

--
-- Name: voucher_header; Type: TABLE; Schema: master; Owner: postgres
--

CREATE TABLE master.voucher_header (
    id uuid NOT NULL,
    voucher_no character varying(50),
    voucher_type character varying(20),
    voucher_date date,
    reference_no character varying(50),
    narration character varying(50),
    voucher_status character varying(15),
    total_debit numeric(18,2),
    total_credit numeric(18,2),
    active character varying(1),
    created_by character varying(100),
    modified_by character varying(100),
    created_date timestamp with time zone,
    modified_date timestamp with time zone,
    company_id uuid,
    voucher_type_id uuid,
    voucher_type_name character varying(100),
    source_document_type character varying(50),
    source_document_id uuid,
    due_date date,
    reference_date date
);


ALTER TABLE master.voucher_header OWNER TO postgres;

--
-- Name: voucher_sequence; Type: TABLE; Schema: master; Owner: postgres
--

CREATE TABLE master.voucher_sequence (
    id uuid NOT NULL,
    voucher_type character varying(20) NOT NULL,
    prefix character varying(10) NOT NULL,
    last_number integer,
    number_width integer,
    active character varying(1),
    created_by character varying(100),
    modified_by character varying(100),
    created_date timestamp with time zone,
    modified_date timestamp with time zone,
    company_id uuid
);


ALTER TABLE master.voucher_sequence OWNER TO postgres;

--
-- Name: voucher_type; Type: TABLE; Schema: master; Owner: postgres
--

CREATE TABLE master.voucher_type (
    id uuid NOT NULL,
    company_id uuid NOT NULL,
    name character varying(100) NOT NULL,
    base_voucher_type character varying(20) NOT NULL,
    abbreviation character varying(20),
    active character varying(1) NOT NULL,
    is_system character varying(1) NOT NULL,
    created_by character varying(100),
    modified_by character varying(100),
    created_date timestamp with time zone,
    modified_date timestamp with time zone
);


ALTER TABLE master.voucher_type OWNER TO postgres;

